param(
    [string]$ProjectRoot = "C:\Users\arauj\grafica-flash"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$ExpectedBranch = "fix/unify-payment-flows-phase-1"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\fase8-desempenho-" + (Get-Date -Format "yyyyMMdd-HHmmss"))

$GeneratedFiles = @{
    "lib/sales-performance.ts" = ""
    "app/api/admin/performance/route.ts" = ""
    "components/admin/SalesPerformanceClient.tsx" = ""
    "app/admin/prospeccao/desempenho/page.tsx" = "aW1wb3J0IFNhbGVzUGVyZm9ybWFuY2VDbGllbnQgZnJvbSAnQC9jb21wb25lbnRzL2FkbWluL1NhbGVzUGVyZm9ybWFuY2VDbGllbnQnCgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBEZXNlbXBlbmhvQ29tZXJjaWFsUGFnZSgpIHsKICByZXR1cm4gPFNhbGVzUGVyZm9ybWFuY2VDbGllbnQgLz4KfQo="
}

$ExpectedSha = @{
    "lib/sales-performance.ts" = "A17941FFEBFC29BB5ABFA9E322D40C647E50C83FACBE771A8D28F86CDC284EAF"
    "app/api/admin/performance/route.ts" = "5F1766C7329FBAC1AD695EDFA2197E39E25C4E1479F9ADCC4FBC478429A4E576"
    "components/admin/SalesPerformanceClient.tsx" = "6311AAF88701DC4CD5BE57A9EBF0FB200E1F4DA5C1D9B392EB888893512BBBAA"
    "app/admin/prospeccao/desempenho/page.tsx" = "654D62318B97795726F7C0E521E5C31CB5074221A50B87198CF083B0F5A75C8D"
}

$PatchBefore = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)
$PatchAfter = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String("")
)

$Changed = New-Object System.Collections.Generic.List[string]
$Backups = @{}

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function FullPath([string]$Relative) {
    return Join-Path $ProjectRoot ($Relative -replace "/", "\")
}

function NormalizeNewlines([string]$Value) {
    if ($null -eq $Value) { return "" }
    return $Value.Replace("`r`n", "`n").Replace("`r", "`n")
}

function Backup([string]$Relative) {
    $source = FullPath $Relative
    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) { return }

    $destination = Join-Path $BackupRoot ($Relative -replace "/", "\")
    [IO.Directory]::CreateDirectory((Split-Path -Parent $destination)) | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination -Force
    $Backups[$Relative] = $destination
}

function MarkChanged([string]$Relative) {
    if (-not $Changed.Contains($Relative)) {
        $Changed.Add($Relative)
    }
}

function WriteBytesWithRetry([string]$Relative, [byte[]]$Bytes) {
    $path = FullPath $Relative
    $directory = Split-Path -Parent $path
    [IO.Directory]::CreateDirectory($directory) | Out-Null

    $temp = Join-Path $directory (
        "." + [IO.Path]::GetFileName($path) + ".orcaly-fase8-" +
        [Guid]::NewGuid().ToString("N") + ".tmp"
    )

    try {
        [IO.File]::WriteAllBytes($temp, $Bytes)
        $written = $false
        $lastError = $null

        for ($attempt = 1; $attempt -le 8; $attempt++) {
            try {
                if (Test-Path -LiteralPath $path -PathType Leaf) {
                    [IO.File]::Copy($temp, $path, $true)
                } else {
                    [IO.File]::Move($temp, $path)
                }
                $written = $true
                break
            } catch {
                $lastError = $_.Exception
                [GC]::Collect()
                [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds (250 * $attempt)
            }
        }

        if (-not $written) {
            throw (
                "Windows manteve o arquivo bloqueado: " + $Relative +
                ". Feche npm run dev/VS Code e tente novamente. " +
                $(if ($lastError) { $lastError.Message } else { "" })
            )
        }
    } finally {
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
}

function WriteTextWithRetry([string]$Relative, [string]$Text) {
    $bytes = [Text.Encoding]::UTF8.GetBytes((NormalizeNewlines $Text))
    WriteBytesWithRetry $Relative $bytes
}

function WriteGenerated([string]$Relative) {
    $path = FullPath $Relative

    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $actual = (Get-FileHash $path -Algorithm SHA256).Hash.ToUpperInvariant()
        if ($actual -eq $ExpectedSha[$Relative]) {
            Ok ($Relative + " ja corresponde a FASE 8.")
            return
        }
        throw ($Relative + " ja existe com conteudo diferente.")
    }

    $bytes = [Convert]::FromBase64String($GeneratedFiles[$Relative])
    WriteBytesWithRetry $Relative $bytes

    $actual = (Get-FileHash (FullPath $Relative) -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($actual -ne $ExpectedSha[$Relative]) {
        throw ("SHA256 inesperado depois de gravar " + $Relative)
    }

    MarkChanged $Relative
    Ok ($Relative + " criado.")
}

function ReplacePerformanceLink {
    $relative = "components/admin/ProspectingCrmClient.tsx"
    $path = FullPath $relative

    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "ProspectingCrmClient.tsx ausente. FASE 4 local nao concluida."
    }

    $text = NormalizeNewlines ([IO.File]::ReadAllText($path))
    $before = NormalizeNewlines $PatchBefore
    $after = NormalizeNewlines $PatchAfter

    if ($text.Contains($after)) {
        Ok "Link Desempenho no CRM ja aplicado."
        return
    }

    $count = 0
    $start = 0
    while ($true) {
        $index = $text.IndexOf($before, $start, [StringComparison]::Ordinal)
        if ($index -lt 0) { break }
        $count++
        $start = $index + $before.Length
    }

    if ($count -ne 1) {
        throw (
            "Trecho do botao Atualizar no CRM encontrado " + $count +
            " vez(es). Nao vou adivinhar o merge."
        )
    }

    Backup $relative
    WriteTextWithRetry $relative ($text.Replace($before, $after))
    MarkChanged $relative
    Ok "Link Desempenho conectado ao CRM."
}

function AssertCheck([bool]$Passed, [string]$Name) {
    if (-not $Passed) {
        throw ("Validacao falhou: " + $Name)
    }
    Ok $Name
}

function Rollback {
    [array]$items = @($Changed)
    [Array]::Reverse($items)

    foreach ($relative in $items) {
        if ($Backups.ContainsKey($relative)) {
            Copy-Item -LiteralPath $Backups[$relative] -Destination (FullPath $relative) -Force
            Warn ("Restaurado: " + $relative)
        } else {
            Remove-Item -LiteralPath (FullPath $relative) -Force -ErrorAction SilentlyContinue
            Warn ("Removido: " + $relative)
        }
    }
}

try {
    Write-Host ""
    Write-Host "ORCALY - FASE 8 - DESEMPENHO COMERCIAL" -ForegroundColor Cyan
    Write-Host "Metricas de carteira, producao e equipe sem expor dados entre Prospectores." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (FullPath "package.json") -PathType Leaf)) {
        throw "Repositorio Orcaly nao encontrado."
    }

    Set-Location $ProjectRoot

    $branch = ([string]((& git branch --show-current) | Select-Object -First 1)).Trim()
    if ($LASTEXITCODE -ne 0) { throw "Nao foi possivel identificar a branch Git." }
    if ($branch -ne $ExpectedBranch) {
        throw ("Branch atual: " + $branch + ". Esperada: " + $ExpectedBranch)
    }

    Step "Validando FASES 2, 4 e 7 locais"

    $required = @(
        "lib/platform-admin.ts",
        "lib/prospecting.ts",
        "app/api/admin/prospecting/route.ts",
        "components/admin/ProspectingCrmClient.tsx",
        "lib/founder-billing.ts",
        "app/api/founders/billing/route.ts",
        "app/api/cron/founder-billing/route.ts",
        "components/subscription/SubscriptionExperience.tsx",
        "components/subscription/FounderSubscriptionPanel.tsx",
        "supabase/migrations/20260812011742_founder_billing_lifecycle_v1.sql"
    )

    foreach ($relative in $required) {
        AssertCheck (
            (Test-Path -LiteralPath (FullPath $relative) -PathType Leaf)
        ) ("Prerequisito presente: " + $relative)
    }

    $platform = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "lib/platform-admin.ts")))
    AssertCheck ($platform.Contains("'performance.view_own'")) "Permissao performance.view_own presente"
    AssertCheck ($platform.Contains("'performance.view_all'")) "Permissao performance.view_all presente"

    $founderBilling = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "lib/founder-billing.ts")))
    AssertCheck ($founderBilling.Contains("updateFounderSubscriptionToNormalPrice")) "FASE 7 local reconhecida"

    Step "Criando dashboard de desempenho"

    WriteGenerated "lib/sales-performance.ts"
    WriteGenerated "app/api/admin/performance/route.ts"
    WriteGenerated "components/admin/SalesPerformanceClient.tsx"
    WriteGenerated "app/admin/prospeccao/desempenho/page.tsx"

    Step "Ligando desempenho ao CRM"
    ReplacePerformanceLink

    Step "Validando isolamento e semantica das metricas"

    $api = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "app/api/admin/performance/route.ts")))
    $client = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "components/admin/SalesPerformanceClient.tsx")))
    $performanceLib = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "lib/sales-performance.ts")))

    AssertCheck ($api.Contains("'performance.view_own'")) "API exige performance.view_own"
    AssertCheck ($api.Contains("'performance.view_all'")) "Owner usa performance.view_all"
    AssertCheck ($api.Contains(".eq(`n            'assigned_to_admin_id',`n            session.admin.id,")) "Prospector filtra carteira no servidor"
    AssertCheck ($api.Contains(".eq(`n            'created_by_admin_id',`n            session.admin.id,")) "Prospector filtra atividade no servidor"
    AssertCheck ($api.Contains("count: 'exact'")) "Prospects criados por Prospector usam contagem sem expor lead reassociado"
    AssertCheck ($api.Contains("invite.founder_number >= 1")) "Founder #00 excluido das metricas"
    AssertCheck ($api.Contains("first_payment_approved")) "Cliente exige primeiro pagamento aprovado"
    AssertCheck ($api.Contains("sales_event_type === 'contact'")) "Contatos medidos por evento real"
    AssertCheck ($api.Contains("sales_event_type === 'stage_change'")) "Avancos medidos por historico de etapa"
    AssertCheck ($performanceLib.Contains("if (denominator <= 0) return 0")) "Taxas com divisor zero retornam 0"
    AssertCheck ($client.Contains("Nenhum Prospector ativo ainda.")) "Dashboard possui estado vazio de equipe"
    AssertCheck ($client.Contains("Dados de outros Prospectores não são enviados")) "UI explicita isolamento individual"

    Step "Confirmando que a FASE 8 nao precisa de migration"
    Ok "Nenhuma tabela, coluna ou RPC nova e necessaria; indices das FASES 4-7 ja cobrem as consultas."

    Step "git diff --check"

    $phase8Files = @(
        "lib/sales-performance.ts",
        "app/api/admin/performance/route.ts",
        "components/admin/SalesPerformanceClient.tsx",
        "app/admin/prospeccao/desempenho/page.tsx",
        "components/admin/ProspectingCrmClient.tsx"
    )

    & git --no-pager diff --check -- $phase8Files
    if ($LASTEXITCODE -ne 0) { throw "git diff --check falhou." }
    Ok "Whitespace validado."

    Step "ESLint direcionado"

    & npx.cmd eslint `
        "lib/sales-performance.ts" `
        "app/api/admin/performance/route.ts" `
        "components/admin/SalesPerformanceClient.tsx" `
        "app/admin/prospeccao/desempenho/page.tsx" `
        "components/admin/ProspectingCrmClient.tsx"

    if ($LASTEXITCODE -ne 0) {
        throw "ESLint direcionado da FASE 8 falhou."
    }
    Ok "ESLint direcionado passou."

    Step "Build completo"

    & npm.cmd run build
    if ($LASTEXITCODE -ne 0) { throw "Build final falhou." }
    Ok "Build final passou."

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " FASE 8 APLICADA E VALIDADA LOCALMENTE" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Implementado:"
    Write-Host " - /admin/prospeccao/desempenho"
    Write-Host " - Periodos 7/30/90 dias e desde o inicio"
    Write-Host " - Carteira atual separada de producao do periodo"
    Write-Host " - Contatos e mudancas de etapa baseados no historico real"
    Write-Host " - Founder #00 excluido"
    Write-Host " - Cliente contado somente apos primeiro pagamento aprovado"
    Write-Host " - Taxa de ativacao dos convites"
    Write-Host " - Taxa de fechamento da carteira"
    Write-Host " - Acoes atrasadas e proximos retornos"
    Write-Host " - Prospector recebe somente os proprios dados"
    Write-Host " - Owner recebe comparativo da equipe"
    Write-Host " - Estado vazio seguro para equipe ainda sem Prospectores"
    Write-Host ""
    Write-Host "Nenhuma migration de banco foi necessaria nesta fase." -ForegroundColor Yellow
    Write-Host "Nenhum commit, push ou deploy foi executado." -ForegroundColor Cyan
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if ($Changed.Count -gt 0) {
        Warn "Executando rollback dos arquivos alterados."
        Rollback
    }

    Write-Host ("Backup: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
